{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 주차장 조례상 건물 부설주차장 장애인전용주차구획 설치 비율",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 주차장 설치 및 관리 조례 제25조 제1항에 따르면, 장애인전용주차구획을 설치하여야 하는 시설물에는 부설주차장 설치기준에 따른 주차대수의 3퍼센트 이상을 장애인전용주차구획으로 구분·설치하여야 합니다. 다만, 부설주차장 설치기준에 따른 주차대수가 10대 미만인 경우에는 그러하지 아니합니다.",
          "b_ids": "주차장:제25조제1항, 주차장:제25조제1항단서"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
